import{_ as e,o as d,c as o,a2 as c}from"./chunks/framework.BGlkWkwp.js";const p=JSON.parse('{"title":"Icon","description":"","frontmatter":{},"headers":[],"relativePath":"components/icon.md","filePath":"components/icon.md"}'),r={name:"components/icon.md"};function a(i,t,n,s,h,l){return d(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="icon" tabindex="-1">Icon <a class="header-anchor" href="#icon" aria-label="Permalink to &quot;Icon&quot;">​</a></h1><p>Icon draws a line icon in the color of the text around it.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it beside text, in a button or at the start of a list item. <code>name</code> takes a name from the <a href="#icons">icons</a> or any icon component, such as a Lucide icon. A button that shows only an icon needs an <code>aria-label</code>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>name</code></td><td>required</td><td>A name from <code>icons</code>, or an icon component</td></tr><tr><td><code>tone</code></td><td></td><td><code>blue</code>, <code>yellow</code>, <code>red</code>, <code>green</code> or <code>muted</code></td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>An icon is a square of <code>--kata-height-icon</code> (the root size) with a stroke of 1.5, in <code>currentColor</code> unless a tone gives it the ink of a hue or the muted color. It never shrinks and has no margin; flex layout centres it. Its white space is never cancelled with a negative margin.</p><h2 id="icons" tabindex="-1">Icons <a class="header-anchor" href="#icons" aria-label="Permalink to &quot;Icons&quot;">​</a></h2><p><code>icons</code> holds the icons the components draw by name. Most come from <a href="https://lucide.dev" target="_blank" rel="noreferrer">Lucide</a>; the drawing glyphs are kata&#39;s own, drawn on the same grid for the shapes Lucide does not have.</p><table tabindex="0"><thead><tr><th>Name</th><th>Drawn by</th></tr></thead><tbody><tr><td><code>arrow-left</code></td><td>Lucide</td></tr><tr><td><code>arrow-up-right</code></td><td>Lucide</td></tr><tr><td><code>check</code></td><td>Lucide</td></tr><tr><td><code>chevron-down</code></td><td>Lucide</td></tr><tr><td><code>chevron-left</code></td><td>Lucide</td></tr><tr><td><code>chevron-right</code></td><td>Lucide</td></tr><tr><td><code>circle-alert</code></td><td>Lucide</td></tr><tr><td><code>circle-check</code></td><td>Lucide</td></tr><tr><td><code>copy</code></td><td>Lucide</td></tr><tr><td><code>corner-up-right</code></td><td>Lucide</td></tr><tr><td><code>ellipsis</code></td><td>Lucide</td></tr><tr><td><code>funnel</code></td><td>Lucide</td></tr><tr><td><code>globe</code></td><td>Lucide</td></tr><tr><td><code>grip-vertical</code></td><td>Lucide</td></tr><tr><td><code>image</code></td><td>Lucide</td></tr><tr><td><code>info</code></td><td>Lucide</td></tr><tr><td><code>pencil</code></td><td>Lucide</td></tr><tr><td><code>pipette</code></td><td>Lucide</td></tr><tr><td><code>plus</code></td><td>Lucide</td></tr><tr><td><code>search</code></td><td>Lucide</td></tr><tr><td><code>settings-2</code></td><td>Lucide</td></tr><tr><td><code>share-2</code></td><td>Lucide</td></tr><tr><td><code>trash-2</code></td><td>Lucide</td></tr><tr><td><code>triangle-alert</code></td><td>Lucide</td></tr><tr><td><code>ungroup</code></td><td>Lucide</td></tr><tr><td><code>x</code></td><td>Lucide</td></tr><tr><td><code>eye</code></td><td>Lucide</td></tr><tr><td><code>eye-off</code></td><td>Lucide</td></tr><tr><td><code>lock</code></td><td>Lucide</td></tr><tr><td><code>lock-open</code></td><td>Lucide</td></tr><tr><td><code>undo-2</code></td><td>Lucide</td></tr><tr><td><code>point</code></td><td>kata</td></tr><tr><td><code>polyline</code></td><td>kata</td></tr><tr><td><code>polygon</code></td><td>kata</td></tr><tr><td><code>arrow</code></td><td>kata</td></tr><tr><td><code>sticky-note</code></td><td>kata</td></tr></tbody></table><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/icon/" title="Icon" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/icon/" target="_blank" rel="noopener">Icon</a></figcaption></figure>',13)])])}const m=e(r,[["render",a]]);export{p as __pageData,m as default};
